const ref = $input.first().json.body.entry[0].changes[0].value.messages[0].referral || {};
const SERVICES = ['construccion_convencional','cargotectura','remodelacion','diseno_arquitectonico','corretaje_venta','corretaje_arriendo','administracion_inmueble','avaluo','inspeccion','consultoria','agente_ia','crm_ia','capacitacion','compra','renta','otro'];

const systemPrompt = `Eres analizador de anuncios Click-to-WhatsApp de 321 Soluciones Inmobiliarias (Quito, Ecuador). Construyen casas convencionales y cargotectura (containers), hacen remodelaciones, corretaje (venta/arriendo), administracion de inmuebles, avaluos, inspecciones, consultorias, y servicios IA.

Devuelve SOLO JSON estricto:
{
  "ad_image_analysis": {
    "producto_principal": string,
    "precio_visible": string|null,
    "cta_observado": string|null,
    "estilo": string,
    "elementos_visuales_clave": string[]
  },
  "service_type_inferred": uno de [${SERVICES.join(', ')}]
}

Si no identificas algo usa null. service_type_inferred es tu mejor inferencia.`;

const userText = `Headline: ${ref.headline || ''}\nBody: ${ref.body || ''}\nSource URL: ${ref.source_url || ''}\nSource type: ${ref.source_type || ''}`;

const userContent = [{ type: 'text', text: userText }];
if (ref.image_url) userContent.push({ type: 'image_url', image_url: { url: ref.image_url } });

return [{
  json: {
    ...$input.first().json,
    _openai_payload: {
      model: 'gpt-4o-mini',
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userContent }
      ]
    }
  }
}];
